import {geoDistance,groupCamera,placeCamera} from '../atlas-core.js';
import {makeRoute,routePoint,roadPose,makeTimeline,sceneAt,scenePose,cameraBlend,ease,clamp} from './tour-core.js';
import {resolveAtlasPolicy} from '../atlas-policy.js';
import {BRIGADE_ORCHARDS_ATLAS_CONFIG} from '../atlas-sites.js';
const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let flat=false,flatMap,flatLib;
let data,policy,route,stops,scenes,total,map,lib,ready=false,playing=false,orbiting=false,elapsed=0,frame=0,token=0,active=-1,sceneKey='',overlays=[],terrain=[],pendingResolve=null,quiet=true,boundaries=true;
const scale=()=>innerWidth<760?(policy?.camera.mobileScale??1.4):1;
function altitude(p){if(!terrain.length)return 900;return terrain.reduce((best,v)=>geoDistance(v,p)<geoDistance(best,p)?v:best).elevation}
function context(){return {home:data.site.center,defaultElevation:altitude(data.site.center),viewportWidth:innerWidth,maxContextDistanceM:5000}}
function applyPolicyPresentation(){
 const has=kind=>policy.mainViews.includes(kind);
 for(const [kind,selectors] of Object.entries({overview:['#overview','#above'],corridor:['.transport'],precinct:['.stops','#orbit'],context:['.locator','#quiet']}))
  for(const selector of selectors){const element=$(selector);if(element)element.hidden=!has(kind)}
}
function overview(top=false){return {...groupCamera(context(),[{boundary:data.site.boundary,elevation:altitude(data.site.center)}]),heading:top?0:345,tilt:top?0:32,range:(top?policy.camera.overviewRangeM*.83:policy.camera.overviewRangeM)*scale()}}
function focusPose(stop,heading=285){const radius=Math.max(...stop.geometry.map(p=>geoDistance(stop.center,p)));return placeCamera(context(),{...stop.center,elevation:altitude(stop.center)},{range:Math.max(policy.camera.focusRangeM,radius*3.2),heading,tilt:58})}
const pose=(s,t)=>scenePose(s,t,{route,altitude,scale,overview,focusPose,stops,scenes,roadRangeM:policy.camera.roadRangeM});
function current(){const c=map.center;return {center:{lat:c.lat,lng:c.lng,altitude:c.altitude},heading:map.heading,range:map.range,tilt:map.tilt}}
function apply(c){map.center=c.center;map.heading=(c.heading%360+360)%360;map.range=c.range;map.tilt=c.tilt;locate(c.center)}
function controls(){if(flat){for(const id of ['play','restart','above','orbit','timeline'])$('#'+id).disabled=true;for(const id of ['overview','boundaries','quiet'])$('#'+id).disabled=!ready;$('#play').textContent='Satellite overview';$('#tourMode').textContent='3D NOT SUPPORTED IN THIS BROWSER';return}for(const id of ['play','restart','above','overview','orbit','timeline','boundaries','quiet'])$('#'+id).disabled=!ready;$('#play').textContent=playing?'Ⅱ Pause tour':elapsed>=total?'↺ Replay tour':elapsed>0?'▶ Resume tour':'▶ Take the tour';$('#orbit').setAttribute('aria-pressed',String(orbiting));$('#tourMode').textContent=playing?'FOLLOWING THE TOWNSHIP':orbiting?'SLOW ORBIT':'EXPLORE AT YOUR OWN PACE';}
function stop(){if(pendingResolve){pendingResolve(false);pendingResolve=null}token++;cancelAnimationFrame(frame);playing=false;orbiting=false;controls()}
function transition(camera,duration=1800){stop();const run=token,from=current(),start=performance.now();return new Promise(resolve=>{pendingResolve=resolve;function tick(now){if(run!==token){resolve(false);return}const t=reduced?1:clamp((now-start)/duration);apply(cameraBlend(from,camera,ease(t)));if(t<1)frame=requestAnimationFrame(tick);else{pendingResolve=null;resolve(true)}}frame=requestAnimationFrame(tick)})}
function setCaption(index,road=false){const key=index+':'+road;if(key===sceneKey)return;sceneKey=key;active=index;const s=stops[index];$('#chapter').textContent=road?'ON THE WAY / SPINAL ROAD':String(index+1).padStart(2,'0')+' / '+s.kicker;$('#title').textContent=road?'Through the township.':s.title;$('#description').textContent=road?'Follow the mapped spinal road towards '+s.name+'. The next precinct stays connected to the journey.':s.description;$('#source').href='https://www.openstreetmap.org/'+s.id;$('#source').textContent=index?'Mapped precinct ↗':'Mapped township ↗';for(const b of document.querySelectorAll('[data-stop]')){const selected=Number(b.dataset.stop)===index;b.classList.toggle('active',selected);b.setAttribute('aria-current',selected?'step':'false')}renderOverlays(road);renderMini(index)}
function updateTime(){const time=ms=>Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');$('#time').textContent=time(elapsed)+' / '+time(total);$('#timeline').value=Math.round(elapsed/total*1000)}
async function play(){if(!ready||flat)return;if(playing){stop();return}if(elapsed>=total)elapsed=0;const sample=sceneAt(scenes,elapsed);if(!await transition(pose(sample.scene,sample.t),1200))return;playing=true;controls();const run=token;let previous=performance.now();function tick(now){if(run!==token)return;elapsed=Math.min(total,elapsed+Math.min(now-previous,100));previous=now;const {scene,t}=sceneAt(scenes,elapsed);setCaption(scene.stop,scene.kind==='road'||scene.kind==='arrival');if(!reduced||sceneKey!==lastReduced){apply(pose(scene,reduced?.5:t));lastReduced=sceneKey}updateTime();if(elapsed<total)frame=requestAnimationFrame(tick);else{stop();setCaption(0);apply(overview())}}let lastReduced='';frame=requestAnimationFrame(tick)}
function add(o){map.append(o);overlays.push(o);return o}
function polygon(points,fill,stroke,width=2){const p=new lib.Polygon3DElement({altitudeMode:'CLAMP_TO_GROUND',fillColor:fill,strokeColor:stroke,strokeWidth:width,drawsOccludedSegments:false});p.path=points;return add(p)}
function renderOverlays(onRoad=false){if(flat){renderFlatOverlays();return}if(!lib||!ready)return;overlays.forEach(o=>o.remove());overlays=[];const selected=stops[Math.max(active,0)];
 if(quiet){const b=data.site.bounds,pad=.018;const veil=polygon([{lat:b.south-pad,lng:b.west-pad},{lat:b.north+pad,lng:b.west-pad},{lat:b.north+pad,lng:b.east+pad},{lat:b.south-pad,lng:b.east+pad}],'#07140eb0','#00000000',0);veil.innerPaths=[active>0&&!onRoad?selected.geometry:data.site.boundary]}
 if(boundaries){polygon(data.site.boundary,'#ffffff00','#d9f6ad99',2);if(active>0&&!onRoad)polygon(selected.geometry,'#d9f6ad0a','#e4ffb7',3)}
 for(const f of data.features.filter(f=>f.category==='road'&&f.name===policy.route.requiredName)){const p=new lib.Polyline3DElement({altitudeMode:'CLAMP_TO_GROUND',strokeColor:active>0&&!onRoad?'#edbb6970':'#edbb69',strokeWidth:3,drawsOccludedSegments:false});p.path=f.geometry;add(p)}
 if(active>0&&!onRoad){const marker=new lib.Marker3DInteractiveElement({position:{...selected.center,altitude:35},altitudeMode:'RELATIVE_TO_GROUND',label:selected.name,drawsWhenOccluded:false});add(marker)}
}
const svgNS='http://www.w3.org/2000/svg';
function xy(p){const b=data.site.bounds;return [22+(p.lng-b.west)/(b.east-b.west)*135,12+(b.north-p.lat)/(b.north-b.south)*284]}
function svgPath(points){return points.map((p,i)=>(i?'L':'M')+xy(p).map(n=>n.toFixed(2)).join(',')).join(' ')}
function svgElement(name,attrs){const el=document.createElementNS(svgNS,name);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);return el}
function renderMini(index){const svg=$('#minimap');svg.replaceChildren();svg.append(svgElement('path',{d:svgPath(data.site.boundary)+' Z',fill:'#d9f6ad0d',stroke:'#c2d7b2','stroke-width':1.2}));for(const f of data.features.filter(f=>f.category==='building'))svg.append(svgElement('path',{d:svgPath(f.geometry),fill:'#a9b9a535',stroke:'none'}));svg.append(svgElement('path',{d:svgPath(route.path),fill:'none',stroke:'#efb86c','stroke-width':2}));if(index>0)svg.append(svgElement('path',{d:svgPath(stops[index].geometry)+' Z',fill:'#d9f6ad66',stroke:'#d9f6ad','stroke-width':1.2}));svg.append(svgElement('circle',{id:'position',cx:95,cy:150,r:4,fill:'#fff',stroke:'#233d22','stroke-width':2}));}
function locate(p){const dot=$('#position');if(dot){const [x,y]=xy(p);dot.setAttribute('cx',x);dot.setAttribute('cy',y)}}
async function select(index){if(!ready)return;stop();setCaption(index);if(flat){const bounds=new google.maps.LatLngBounds();stops[index].geometry.forEach(p=>bounds.extend(p));flatMap.fitBounds(bounds,{top:100,bottom:230,left:innerWidth>760?310:40,right:innerWidth>760?240:40});return}const scene=index?scenes.find(s=>s.kind==='focus'&&s.stop===index):scenes[0];elapsed=scene.start+(index?scene.duration*.4:0);updateTime();await transition(index?focusPose(stops[index]):overview());controls()}
function fail(message){ready=false;stop();$('#status').textContent='Aerial view unavailable';$('#error').textContent=message;$('#notice').hidden=false;document.querySelectorAll('[data-stop]').forEach(b=>b.disabled=true)}
window.gm_authFailure=()=>fail('Google Maps access could not be verified for this website.');
async function loadMaps(){if(window.google?.maps?.importLibrary)return;await new Promise((resolve,reject)=>{let timer;window.__brigadeMapsReady=()=>{clearTimeout(timer);resolve()};const s=document.createElement('script');s.src='https://maps.googleapis.com/maps/api/js?'+new URLSearchParams({key:window.ATLAS_CONFIG.mapsKey,v:'weekly',loading:'async',callback:'__brigadeMapsReady'});s.async=true;s.onerror=()=>{clearTimeout(timer);reject(new Error('Google Maps could not be reached.'))};timer=setTimeout(()=>reject(new Error('Google Maps took too long to respond.')),25000);document.head.append(s)})}
function renderFlatOverlays(){if(!flatMap)return;overlays.forEach(o=>o.setMap(null));overlays=[];const selected=stops[Math.max(0,active)];const poly=(paths,strokeColor,fillOpacity,fillColor='#d9f6ad')=>{const p=new google.maps.Polygon({paths,map:flatMap,strokeColor,strokeOpacity:.85,strokeWeight:2,fillColor,fillOpacity,clickable:false});overlays.push(p)};
 if(quiet){const b=data.site.bounds;poly([[{lat:b.south-.02,lng:b.west-.02},{lat:b.north+.02,lng:b.west-.02},{lat:b.north+.02,lng:b.east+.02},{lat:b.south-.02,lng:b.east+.02}], [...selected.geometry].reverse()],'#07140e',.6,'#07140e')}
 if(boundaries){poly(data.site.boundary,'#d9f6ad',0);if(active>0)poly(selected.geometry,'#e3ffb5',.09)}
 const road=new google.maps.Polyline({path:route.path,map:flatMap,strokeColor:'#efb86c',strokeWeight:3,clickable:false});overlays.push(road);
}
async function satellite(){flat=true;flatLib=await google.maps.importLibrary('maps');flatMap=new flatLib.Map($('#map'),{center:data.site.center,zoom:15,mapTypeId:'satellite',renderingType:'RASTER',disableDefaultUI:true,gestureHandling:'greedy'});ready=true;$('#status').textContent='SATELLITE OVERVIEW · 3D UNAVAILABLE';$('#hint').textContent='This browser does not support 3D. Select a precinct to explore the map.';$('#time').textContent='';document.querySelectorAll('[data-stop]').forEach(b=>b.disabled=false);setCaption(0);controls();select(0);flatMap.addListener('center_changed',()=>{const c=flatMap.getCenter();if(c)locate({lat:c.lat(),lng:c.lng()})});}
async function init(){try{
 const response=await fetch('/brigade/inventory.json');if(!response.ok)throw new Error('The township data could not load.');data=await response.json();
 policy=resolveAtlasPolicy({config:BRIGADE_ORCHARDS_ATLAS_CONFIG,site:data.site,features:data.features});document.body.dataset.atlasProfile=policy.profile;document.body.dataset.backdropLayout=policy.backdrop.layout;applyPolicyPresentation();
 const spinal=data.features.filter(f=>f.name===policy.route.requiredName).map(f=>({f,r:makeRoute(f.geometry)})).sort((a,b)=>b.r.length-a.r.length)[0];if(!spinal)throw new Error('The configured tour road is missing.');route=spinal.r;
 const copies=BRIGADE_ORCHARDS_ATLAS_CONFIG.tour.stops;
 const descriptions=BRIGADE_ORCHARDS_ATLAS_CONFIG.tour.stopIds.map((id,index)=>[id,...copies[index]]);
 stops=[{id:data.site.id,name:'Whole township',kicker:'FIND YOUR BEARINGS',title:'The whole picture.',description:'Follow the spinal road through the township, then pause over the places along it.',center:data.site.center,geometry:data.site.boundary},...descriptions.map(([id,name,kicker,title,description])=>{const f=data.features.find(f=>f.id===id);if(!f)throw new Error('A mapped tour stop is missing.');return {...f,name,kicker,title,description}})];
 scenes=makeTimeline(route,stops);total=scenes.at(-1).end;stops.forEach((s,i)=>{const b=document.createElement('button');b.dataset.stop=i;b.disabled=true;const n=document.createElement('span');n.textContent=String(i+1).padStart(2,'0');b.append(n,document.createTextNode(s.name));b.onclick=()=>select(i);$('#stopList').append(b)});renderMini(0);updateTime();
 if(!window.ATLAS_CONFIG?.mapsKey)throw new Error('The Maps connection is not configured.');await loadMaps();const probe=document.createElement('canvas');const gl=probe.getContext('webgl2');if(!gl){await satellite();return}gl.getExtension('WEBGL_lose_context')?.loseContext();lib=await google.maps.importLibrary('maps3d');
 try{const {ElevationService}=await google.maps.importLibrary('elevation');const locations=Array.from({length:10},(_,i)=>routePoint(route,route.length*i/9));const {results}=await new ElevationService().getElevationForLocations({locations});terrain=results.map(v=>({lat:v.location.lat(),lng:v.location.lng(),elevation:v.elevation}));}catch{throw new Error('Terrain height could not be loaded. Please retry so the aerial cameras can be positioned correctly.');}
 map=new lib.Map3DElement({...overview(),mode:'SATELLITE',defaultUIHidden:true,gestureHandling:'GREEDY'});$('#map').replaceChildren(map);
 let settled=false;const timer=setTimeout(()=>{if(!settled)fail('The 3D imagery has not finished loading. Retry the aerial view.')},40000);
 map.addEventListener('gmp-steadychange',e=>{if(e.isSteady&&!settled){settled=true;clearTimeout(timer);ready=true;$('#notice').hidden=true;$('#status').textContent='GOOGLE 3D · MAPPED TOWNSHIP';document.querySelectorAll('[data-stop]').forEach(b=>b.disabled=false);controls();setCaption(0);apply(overview())}});
 map.addEventListener('gmp-error',()=>fail('Google could not render this aerial view. Please retry.'));
 for(const event of ['pointerdown','wheel','touchstart'])map.addEventListener(event,()=>{stop();$('#tourMode').textContent='EXPLORING · RESUME ANYTIME'},{passive:true});
 map.addEventListener('gmp-centerchange',()=>{if(!playing)locate(map.center)});
 }catch(error){fail(error.message)}}
$('#play').onclick=play;$('#retry').onclick=()=>location.reload();$('#restart').onclick=()=>{elapsed=0;play()};$('#overview').onclick=()=>select(0);
$('#above').onclick=()=>{if(ready)transition(active>0?{...focusPose(stops[active]),tilt:0,heading:0}:overview(true))};
$('#orbit').onclick=()=>{if(!ready)return;if(orbiting){stop();return}stop();orbiting=true;controls();const run=token,start=performance.now(),c=current();function tick(now){if(run!==token)return;apply({...c,heading:c.heading+(now-start)/220});frame=requestAnimationFrame(tick)}if(reduced){apply({...c,heading:c.heading+35});stop()}else frame=requestAnimationFrame(tick)};
$('#timeline').oninput=e=>{if(!ready)return;stop();elapsed=Number(e.target.value)/1000*total;const {scene,t}=sceneAt(scenes,elapsed);setCaption(scene.stop,scene.kind==='road'||scene.kind==='arrival');apply(pose(scene,t));updateTime();controls()};
$('#boundaries').onclick=()=>{boundaries=!boundaries;$('#boundaries').setAttribute('aria-pressed',String(boundaries));renderOverlays(sceneKey.endsWith(':true'))};
$('#quiet').onclick=()=>{quiet=!quiet;$('#quiet').setAttribute('aria-pressed',String(quiet));renderOverlays(sceneKey.endsWith(':true'))};
function cinema(value){document.body.classList.toggle('cinema',value);$('#restore').hidden=!value;$('#cinema').setAttribute('aria-pressed',String(value))}
$('#cinema').onclick=()=>cinema(true);$('#restore').onclick=()=>cinema(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'){stop();cinema(false)}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
init();
